using marble_physics::Mem;
using marble_physics::PLAYER;
using marble_flow::Flow;

// player fields
static const uint8_t SLOT = 0x18, VISIBLE = 0x1c, SX = 0x1e, SY = 0x20, MASKS = 0x38;
static const uint8_t ANIM = 0x5a, SHARDS = 0x62, SHARDS_ON = 0x67;
static const uint8_t TIMER = 0x6a, TICKS = 0x6e, SCORE = 0xbc, DEATHS = 0xd2;
static const uint8_t MASK_BYTES = 30, TIMER_STOPPED = 0xff, TICKS_START = 5, OUT_OF_PLAY = 3;
static const uint32_t RNG = 0x4003a6;
static const uint16_t RNG_TICK = 0x100;
static const uint8_t FRAMES_TO_START = 6;  // marble_flow: 0x400010 race end to race start
static const uint8_t TOL = 1;              // frames: fitted intro/load counts vs MAME

static uint8_t ram[marble_physics::RAM_SIZE];

// One main loop tick as marble_sim.py main_tick: 0x400010 and the camera long are inputs,
// then 0x1344c, band spawns (before the camera store), player 0x251de, enemies, slots, rng.
static void mainTick(Mem &m, int8_t c6, int8_t c7, uint32_t camera, uint32_t frames) {
  m.wl(marble_physics::FRAMES, frames);
  marble_objects::applyQueued(m);
  const uint16_t old = m.rw(marble_physics::CAMERA);
  if ((uint16_t)camera != old) { marble_objects::cameraBands(m, old, (int16_t)camera); }
  m.wl(marble_physics::CAMERA_L, camera);
  marble_physics::tick(m, c6, c7);
  marble_enemies::update(m);
  marble_objects::update(m);
  marble_rng::rng(m, RNG_TICK);
}

// marble.cpp run_frame + logicTick of a logic frame, no input
static void logicTick(Mem &m) {
  m.wl(marble_physics::FRAMES, m.rl(marble_physics::FRAMES) + 1);
  marble_objects::applyQueued(m);
  const int16_t oldCam = m.sw(marble_physics::CAMERA);
  const uint32_t oldL = m.rl(marble_physics::CAMERA_L);
  marble_camera::tick(m);
  const int16_t newCam = m.sw(marble_physics::CAMERA);
  if (newCam != oldCam) {  // as marble.cpp: spawns before the camera store
    const uint32_t newL = m.rl(marble_physics::CAMERA_L);
    m.wl(marble_physics::CAMERA_L, oldL);
    marble_objects::cameraBands(m, oldCam, newCam);
    m.wl(marble_physics::CAMERA_L, newL);
  }
  marble_physics::tick(m, 0, 0);
  marble_enemies::update(m);
  marble_objects::update(m);
  marble_rng::rng(m, RNG_TICK);
  marble_drawlist::sort(m);
}

// marble.cpp loadRace: carry, cleared work RAM, race start, the flow's race init
static void loadRace(Flow &f) {
  const marble_flow::Carry c = marble_flow::carry(f, Mem(ram, 0));
  memset(ram, 0, sizeof(ram));
  Mem m(ram, f.race);
  marble_flow::restore(m, c);
  marble_physics::startRace(m, f.race);
  marble_flow::raceLoaded(f, m);
  marble_camera::start(m, f.race);
  marble_physics::project(m);
  marble_occlusion::enter(m, PLAYER);
}

// marble.cpp run_frame without input; returns the phase after the frame
struct Machine {
  Flow flow;
  bool odd;
  uint8_t race;
  marble_hud::Tracker tracker;
  marble_video::Hud hud;
};

static marble_flow::Phase runFrame(Machine &mc, bool start) {
  Mem m(ram, mc.race);
  const marble_flow::Step step = marble_flow::frame(mc.flow, m, start);
  if (step == marble_flow::START_RACE) {
    loadRace(mc.flow);
    mc.race = mc.flow.race;
    mc.odd = true;
  }
  if (step == marble_flow::LOGIC) {
    mc.odd = !mc.odd;
    if (!mc.odd) { logicTick(m); }
  }
  const Mem after(ram, mc.race);
  marble_hud::update(mc.tracker, mc.flow, after, mc.hud);  // marble.cpp publish
  return marble_flow::phase(after);
}

static void newGame(Machine &mc) {
  mc = Machine{};
  marble_flow::newGame(mc.flow);
  memset(ram, 0, sizeof(ram));
  runFrame(mc, false);  // loads practice
}

static void assertNear(uint16_t want, uint16_t got, const char *what, uint8_t race) {
  char msg[96];
  snprintf(msg, sizeof(msg), "race %d %s: MAME %d, remake %d", race, what, want, got);
  TEST_ASSERT_TRUE_MESSAGE(got + TOL >= want && got <= want + TOL, msg);
}

// Practice from a new game: intro, 60 s run out (MAME: 3660 frames after the race start
// frame), 182 frames to game over, START loads practice again
static void test_time_out(void) {
  Machine mc;
  newGame(mc);
  uint16_t n = 0;
  while (runFrame(mc, false) != marble_flow::RACE && n < 1000) { n++; }
  Mem m(ram, mc.race);
  TEST_ASSERT_EQUAL_INT16(MARBLE_TIMEOUT_SECONDS, m.sw(PLAYER + TIMER));

  uint16_t k = 0;
  while (runFrame(mc, false) == marble_flow::RACE && k < 5000) { k++; }
  TEST_ASSERT_EQUAL_UINT16(MARBLE_TIMEOUT_FRAMES, k + 1);
  TEST_ASSERT_EQUAL_UINT16(marble_flow::TIME_OUT, marble_flow::phase(m));
  TEST_ASSERT_EQUAL_UINT8(2, m.rb(PLAYER + SLOT));
  TEST_ASSERT_EQUAL_UINT8(TIMER_STOPPED, m.rb(PLAYER + TICKS));

  k = 0;
  while (runFrame(mc, false) == marble_flow::TIME_OUT && k < 1000) { k++; }
  TEST_ASSERT_EQUAL_UINT16(MARBLE_TIMEOUT_GAME_OVER, k + 1);
  TEST_ASSERT_EQUAL_UINT16(marble_flow::GAME_OVER, marble_flow::phase(m));

  for (k = 0; k < 100; k++) { runFrame(mc, false); }
  TEST_ASSERT_EQUAL_UINT16(marble_flow::GAME_OVER, marble_flow::phase(m));
  runFrame(mc, true);
  runFrame(mc, false);
  TEST_ASSERT_EQUAL_UINT16(marble_flow::GAME_START, marble_flow::phase(Mem(ram, mc.race)));
  TEST_ASSERT_EQUAL_UINT32(0, Mem(ram, mc.race).rl(PLAYER + SCORE));
}

// Race end of each MAME trace: the player out of play after the goal (timer stopped), then
// frame offsets (+-TOL) and values (exact) of bonus, next race intro, final bonus
// race e on, the player out of play after the goal (timer stopped), 0x400390 = 3 set by the
// logic tick of frame 0 (the race end sync frame); the HUD shows the race
static void startRaceEnd(Machine &mc, uint8_t race, int16_t seconds, uint32_t score,
                         uint16_t deaths, uint32_t frames) {
  mc = Machine{};
  mc.flow.race = race;
  mc.race = race;
  loadRace(mc.flow);
  Mem m(ram, race);
  m.ww(PLAYER + TIMER, seconds);
  m.wb(PLAYER + TICKS, TIMER_STOPPED);
  m.wl(PLAYER + SCORE, score);
  m.ww(PLAYER + DEATHS, deaths);
  m.wl(marble_physics::FRAMES, frames);
  m.wb(PLAYER + SLOT, OUT_OF_PLAY);
  mc.flow.phase = marble_flow::RACE;
  mc.flow.intro = marble_flow::NO_INTRO;
  mc.tracker.phase = marble_flow::RACE;
  mc.tracker.loaded = true;
  mc.tracker.score = score;
  m.ww(marble_flow::GAME_STATE, marble_flow::RACE_END);
  marble_hud::update(mc.tracker, mc.flow, m, mc.hud);
}

static void test_race_ends(void) {
  for (const MarbleRaceEnd &e : marble_race_ends) {
    Machine mc;
    startRaceEnd(mc, e.race, e.seconds, e.score, e.deaths, e.frames);

    uint16_t next = 0, bonus = 0, init = 0, firstAdd = 0, raceOn = 0, fin = 0, finLast = 0;
    uint16_t over = 0;
    uint8_t adds = 0;
    uint32_t bonusScore = 0, finalScore = 0;
    for (uint16_t d = 1; d < 1200 && !raceOn && !over; d++) {
      Mem a(ram, mc.race);
      const uint16_t raceWord = a.rw(marble_physics::RACE), secs = a.rw(PLAYER + TIMER);
      const uint32_t score = a.rl(PLAYER + SCORE);
      const marble_flow::Phase before = marble_flow::phase(a);
      const uint8_t r0 = mc.race;
      const marble_flow::Phase now = runFrame(mc, false);
      Mem b(ram, mc.race);

      if (mc.race != r0) { init = d; continue; }
      if (b.rw(marble_physics::RACE) != raceWord && !next) { next = d; }
      if (b.rl(PLAYER + SCORE) != score && !bonus) { bonus = d; bonusScore = b.rl(PLAYER + SCORE); }
      if (init && b.rw(PLAYER + TIMER) == secs + 5) {
        if (!adds++) { firstAdd = d; }
      }
      if (init && now == marble_flow::RACE) { raceOn = d; }
      if (now == marble_flow::FINAL && before != marble_flow::FINAL) { fin = d; }
      if (now == marble_flow::FINAL && b.rl(PLAYER + SCORE) != score) {
        finLast = d;
        finalScore = b.rl(PLAYER + SCORE);
      }
      if (now == marble_flow::GAME_OVER) { over = d; }
    }

    assertNear(e.next, next, "race index", e.race);
    assertNear(e.bonus, bonus, "bonus", e.race);
    TEST_ASSERT_EQUAL_UINT32(e.bonus_score, bonusScore);
    if (e.race_on) {
      assertNear(e.init, init, "init", e.race);
      assertNear(e.first_add, firstAdd, "first +5 s", e.race);
      TEST_ASSERT_EQUAL_UINT8(e.adds, adds);
      assertNear(e.race_on, raceOn, "race start", e.race);
      Mem b(ram, mc.race);
      TEST_ASSERT_EQUAL_UINT16(e.seconds_on, b.rw(PLAYER + TIMER));
      TEST_ASSERT_EQUAL_UINT32(e.frames_on, b.rl(marble_physics::FRAMES));
      TEST_ASSERT_EQUAL_UINT8(TICKS_START, b.rb(PLAYER + TICKS));
    } else {
      assertNear(e.final, fin, "final", e.race);
      assertNear(e.final_last, finLast, "final last points", e.race);
      TEST_ASSERT_EQUAL_UINT32(e.final_score, finalScore);
      assertNear(e.game_over, over, "game over", e.race);
    }
  }
}

// crc32 of player bytes marble_carry_key, the RNG word and the slots, as marble_flow.py key_crc
static uint32_t keyCrc(const Mem &m) {
  static const uint32_t SLOTS = 0x400a9c, SLOTS_END = 0x401300;
  uint32_t crc = ~0u;
  auto add = [&crc](uint8_t v) {
    crc ^= v;
    for (uint8_t k = 0; k < 8; k++) { crc = (crc >> 1) ^ (0xedb88320u & (0u - (crc & 1))); }
  };
  for (uint8_t o : marble_carry_key) { add(m.rb(PLAYER + o)); }
  add(m.rb(RNG));
  add(m.rb(RNG + 1));
  for (uint32_t a = SLOTS; a < SLOTS_END; a++) { add(m.rb(a)); }
  return ~crc;
}

// Next race from a cleared RAM and the carried bytes (marble.cpp loadRace order) equals the
// model run that equals MAME for MARBLE_CARRY_TICKS idle ticks
static void test_carry(void) {
  for (const MarbleCarry &c : marble_carries) {
    marble_flow::Carry k = {};
    memcpy(k.timer, c.timer, sizeof(k.timer));
    k.score = c.score;
    k.deaths = c.deaths;
    k.rng = c.rng;
    k.frames = c.frames - FRAMES_TO_START;
    memset(ram, 0, sizeof(ram));
    Mem m(ram, c.race);
    marble_flow::restore(m, k);
    marble_physics::startRace(m, c.race);
    marble_physics::project(m);
    marble_occlusion::enter(m, PLAYER);
    for (uint16_t t = 0; t < MARBLE_CARRY_TICKS; t++) {
      mainTick(m, 0, 0, c.camera, m.rl(marble_physics::FRAMES) + 1);
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "race %d carry run", c.race);
    TEST_ASSERT_EQUAL_HEX32_MESSAGE(c.crc, keyCrc(m), msg);
  }
}

// first field of tick t that differs, nullptr if none
static const char *diff(const Mem &m, const MarbleBonusTick &t) {
  if (marble_physics::x(m) != t.x) { return "x"; }
  if (marble_physics::y(m) != t.y) { return "y"; }
  if (marble_physics::z(m) != t.z) { return "z"; }
  if (marble_physics::state(m) != t.state) { return "state"; }
  if (m.rb(PLAYER + VISIBLE) != t.vis) { return "vis"; }
  if (m.sw(PLAYER + SX) != t.sx) { return "sx"; }
  if (m.sw(PLAYER + SY) != t.sy) { return "sy"; }
  if (m.rl(PLAYER + ANIM) != t.anim) { return "anim"; }
  if (m.rb(PLAYER + SHARDS_ON) && m.roml(m.rl(PLAYER + SHARDS)) != t.shard_hdr) { return "shards"; }
  if (memcmp(ram + (PLAYER + MASKS - marble_physics::RAM_BASE), t.mask, MASK_BYTES)) {
    return "mask";
  }
  if (m.rw(RNG) != t.rng) { return "rng"; }
  return nullptr;
}

// MAME segment: 0x1bbaa time bonus event, state 8 for 90 ticks (+10 s), then rolling
static void test_replay_bonus(void) {
  for (uint8_t s = 0; s < MARBLE_BONUS_SEGMENTS; s++) {
    const MarbleBonusSegment &seg = marble_bonuses_segments[s];
    memset(ram, 0, sizeof(ram));
    for (uint8_t i = 0; i < seg.nram; i++) {
      const MarbleBonusRam &r = seg.ram[i];
      memcpy(ram + (r.addr - marble_physics::RAM_BASE), r.bytes, r.len);
    }
    Mem m(ram, seg.race);
    marble_drawlist::init(m);  // the fixture has no draw list; slot inserts need one
    const int16_t s0 = m.sw(PLAYER + TIMER);

    uint16_t bonusTicks = 0;
    for (uint16_t k = 0; k < seg.nticks; k++) {
      const MarbleBonusTick &t = seg.ticks[k];
      mainTick(m, t.c6, t.c7, t.camera, t.frames);
      bonusTicks += marble_physics::state(m) == marble_physics::TIME_BONUS;
      const char *bad = diff(m, t);
      if (!bad) { continue; }

      char msg[160];
      snprintf(msg, sizeof(msg), "bonus segment %d tick %d: %s differs (state %d, expected %d)",
               s, k, bad, marble_physics::state(m), t.state);
      TEST_FAIL_MESSAGE(msg);
    }
    TEST_ASSERT_EQUAL_UINT16(90, bonusTicks);
    TEST_ASSERT_EQUAL_INT16(s0 + 10, m.sw(PLAYER + TIMER));  // the logic adds, the IRQ paused
  }
}

// expected HUD step at frame offset d (the last step at or before d)
static const MarbleHudStep &stepAt(const MarbleHudRun &r, int d) {
  uint16_t k = 0;
  while (k + 1 < r.nsteps && (int)r.steps[k + 1].at <= d) { k++; }
  return r.steps[k];
}

static bool same(const marble_video::Hud &h, const MarbleHudStep &s) {
  return h.screen == s.screen && h.pal3 == s.pal3 && h.pal11 == s.pal11 && h.add == s.add &&
         h.value == s.value;
}

// HUD of frame d equals the model at d - TOL .. d + TOL
static void checkHud(const MarbleHudRun &r, int d, const marble_video::Hud &h) {
  for (int k = -TOL; k <= TOL; k++) {
    if (same(h, stepAt(r, d + k))) { return; }
  }
  const MarbleHudStep &s = stepAt(r, d);
  char msg[160];
  snprintf(msg, sizeof(msg), "race %d frame %d: screen 0x%x pal %d/%d add %d value %d, MAME "
           "0x%x %d/%d %d %d", r.race, d, h.screen, h.pal3, h.pal11, h.add, (int)h.value,
           s.screen, s.pal3, s.pal11, s.add, (int)s.value);
  TEST_FAIL_MESSAGE(msg);
}

// new game to game over (practice time out): every frame from the race init
static void test_hud_time_out(void) {
  const MarbleHudRun &r = marble_hud_runs[0];
  TEST_ASSERT_EQUAL_UINT8(MARBLE_HUD_SYNC_INIT, r.sync);
  Machine mc;
  newGame(mc);  // frame 0: race init
  checkHud(r, 0, mc.hud);
  for (int d = 1; d < r.frames; d++) {
    runFrame(mc, false);
    checkHud(r, d, mc.hud);
  }
}

// race end of every race: bonus line and palette, level load, next intro / final screen
static void test_hud_race_ends(void) {
  for (uint8_t k = 1; k < sizeof(marble_hud_runs) / sizeof(marble_hud_runs[0]); k++) {
    const MarbleHudRun &r = marble_hud_runs[k];
    TEST_ASSERT_EQUAL_UINT8(MARBLE_HUD_SYNC_RACE_END, r.sync);
    Machine mc;
    startRaceEnd(mc, r.race, r.seconds, r.score, r.deaths, r.frames0);
    checkHud(r, 0, mc.hud);
    for (int d = 1; d < r.frames; d++) {
      runFrame(mc, false);
      checkHud(r, d, mc.hud);
    }
  }
}

// after game over: PUSH 1 PLAYER START until START, then the new game's race init
static void test_hud_push_start(void) {
  Machine mc;
  newGame(mc);
  uint16_t n = 0;
  while (runFrame(mc, false) != marble_flow::GAME_OVER && n < 5000) { n++; }
  for (n = 0; n < 10; n++) { runFrame(mc, false); }
  TEST_ASSERT_EQUAL_HEX16(marble_hud::PAL | marble_hud::PUSH, mc.hud.screen);
  runFrame(mc, true);
  runFrame(mc, false);
  TEST_ASSERT_EQUAL_HEX16(0, mc.hud.screen);  // level load: nothing shows
}
#endif

int main(int, char **) {
  UNITY_BEGIN();
#ifdef HAVE_ROM
  RUN_TEST(test_time_out);
  RUN_TEST(test_race_ends);
  RUN_TEST(test_carry);
  RUN_TEST(test_replay_bonus);
  RUN_TEST(test_hud_time_out);
  RUN_TEST(test_hud_race_ends);
  RUN_TEST(test_hud_push_start);
#else
  TEST_IGNORE_MESSAGE("marble_rom.h missing, run romconv ./convert.sh marble");
#endif
  return UNITY_END();
}
